    if (value instanceof ArrayBuffer) return [value];
    // Support for objects that contain a buffer (e.g. TypedArrays returned from .NET)
    if (value && typeof value === 'object' && value.buffer instanceof ArrayBuffer) {
        return [value.buffer];
    }
    return [];
}

